   "mice-bWFuIHRydWNrICYgYnVzIC0g": "<TYO-1763 与ICT相关的D类参观> 调查 *因新冠肺炎疫情影响取消*\n\n☆ 日期和时间\n\n2020年11月18日（周三）14:00~ *请在参观开始时间前至少15分钟到达。\n\n☆ 人数\n\n25＋1\n富士通家庭协会\n\n☆ 联系方式\n\nBui Dieu 先生\n(werksfuehrung-muc@man.eu / +49 (0)89 1580 3826)\n\n☆ 行程示例\n\n私人紧凑型参观（1.5小时）⇒ 考虑到翻译时间，总参观时长约为2小时。\n简要介绍、卡车装配、驾驶室装配等。\nhttps://man-factory-tour.diva-agency.de/#regdl=kompakt-tour-27264\n\n参观语言为德语。\n\n☆ 参观费用\n\nEUR 230 每人（含增值税）\n仅接受现场付款\n\n☆ 条件\n\n参观前1周内取消免费，此后取消将收取全额费用。\n\n☆ 特别说明\n\n- 必须在参观前至少一周提交名单。\n- 参观当天请携带护照或其他身份证件。\n- 出于安全原因，请穿着牢固的封闭式鞋头鞋。\n- MAN Truck & Bus 保留在参观前临时更改内容或因运营原因取消的权利。我们不对任何间接损失负责。\n\n---------------------------------\n\n<OSA-0616 2019年模具博览会> 调查 *因客户不足而取消*\n\n截至2019年3月，MAN工厂中仅纽伦堡工厂接受外部参观。\n\n一般而言，慕尼黑和奥格斯堡工厂的参观仅限于MAN巴士车主和前来提车的客户。仅在有余位的情况下，我们才会回应其他人士的请求。\n\n---------------------------------------------\n\n<TTAO229121-20NOV18 TTTB04 “A) 岩手产业学院（11月）”（TYO-1614）>\n\n☆ 日期和时间\n\n2018年11月22日（周四）上午\n\n☆ 人数\n\n学生22＋领队1＋翻译\n岩手县立产业技术学院\n\n☆ 答复\n\n我希望安排紧凑型参观（1.5小时），但截至10月中旬，11月份的所有参观时段均已约满。\n\n---------------------------------------------\n\n<TYO-1311 与巴士相关的商务电视参观 I/N/C/H/D/I>\n\n☆ 日期和时间\n\n2016年10月12日至20日\n\n☆ 人数\n\n10-20＋1\n日本巴士协会的会员组织和公司员工\n\n☆ 负责人\n\nSchultz 女士，“MAN 慕尼黑体验参观”（MAN 慕尼黑导览参观）\n\n☆ 答复\n\n已接受在慕尼黑工厂进行，该工厂提供导览参观服务。\n提交您期望的参观日期和时间后将获得正式许可，但如果您告知期望的日期时间和计划人数，可以预留参观时段，且似乎可以在之后提交团体详细信息。\n\n该工厂仅生产卡车（该团体希望参观巴士），但据负责人介绍，“独家牵引车参观”项目可以让您看到车桥装配线，甚至可以在讲解中加入巴士生产的故事。\n\n（“独家牵引车参观”项目信息：见附件PDF）\n时长2.5小时\n语言：德语、英语、法语、西班牙语\n价格：EUR 250 每人\n人数：每组最多30人",
   "mice-Ym9yZCBiaWEgLSBpcmlzaCBm": "致：TTV\n该内容也已注册在“29. 行政管理”类别中。\n\n＝＝＝＝＝＝＝＝＝＝＝＝＝\n\nTTAO214342-07OCT17 NECD26 A) 东京经营者协会（GRQ TYO-1431）10+1\n=> 无法接受。\n\nOSA-0480 已被接受，但由于东京经营者协会的主题是工作环境和就业，因此本次因无法实现而予以拒绝。\n\n-----------------------------------\n\nOOAO094443-21JUN17 NECL11 A) NEC 大阪旅行经营合理化（GRQ OSA-0480）\n\n回复：\n2017年6月22日（周四）14:00-15:30（所需时间：约1个半小时）\n\n人数：\n预计人数10-15＋1？？\n\n负责人：\nLiam Keane 先生（Kennedy 的同事）\n※ David Kennedy 先生（国际市场经理）将在参观当天出差海外，很遗憾当天无法出席，但会有替代人员，参观将按计划进行。\n\n行程：\n在总部办公室进行欢迎、演示和问答环节。\n* 我们计划尽可能多地涵盖爱尔兰食品饮料行业概况、爱尔兰食品管理局以及主题案例等内容。\n* 讲座主题示例。\n- 组织及活动介绍。\n- 关于特点。\n- 食品行业现状等。\n- （如有可能，提供办公室信息）\n\n费用：\n免费。\n请携带一份纪念品作为回礼。\n\n所需信息：\n请提前提交一份了解您背景和行业的成员名单。",
   "mice-dGF5dG8gY3Jpc3Bz": "OOAO094443-21JUN17 NECL11 A) NEC 大阪旅行经营合理化（GRQ OSA-0480）=> 经批准后，取消并前往客户安排的地点\n\n回复：\n2017年6月23日（周五）上午 *时间正在确认中。\n\n人数：\n预计人数10-15＋1？？\n\n行程：\nTayto 工厂参观（http://www.taytopark.ie/theme-park/tayto-factory-tour）\n参观主要薯片制造商 Tayto 的工厂。\n内容包含公园门票、工厂参观、园区游览（动物园等）以及一个主题公园（*）游乐设施。\n无法进入工厂车间，但可以在导览路线上通过窗户参观。\n由于工厂参观导游的讲解限制，我们无法提供有关公司财务等细节信息。* 通常的工厂参观为自助式，但本次为私人参观。\n工厂位于 Tayto 公园内（Tayto 主题公园，毗邻游乐园和动物园设施）。\n\n费用（含税）：\nEUR15 每人（含门票和参观费）。\n* 最低接受人数为15人，最高为30人。\n⇒ 预计人数为10-15+1人，因此如果不足15人，请考虑需要按15人付费。",
   "mice-YXppZW5kYSBhZ3JpY29sYSBh": "技术参观 + 午餐\n\n行程安排：\n - 轻松品尝（自制蛋糕、果酱、咖啡、茶等）\n - 农场及活动介绍，参观农场和设施，问答环节\n - 午餐\n*菜单：第一道菜、第二道菜 + 配菜 + 水 + 葡萄酒 + 咖啡",
   "mice-YWdyaWNvbHR1cmEgbnVvdmE": "语言：意大利语\n行程安排；农场介绍及设施参观\n - 简要介绍农场及其生产、加工、销售等流程\n - 设施导览（农场、加工厂、农场商店等）\n - 奶酪品尝 ### 可选项目 ###\n - 问答\n - 午餐 ### 可选项目 ###\n\n☆特别说明\n\n午餐在员工食堂供应。菜单每日更换，无法提前查看具体内容。此外，我们无法满足菜单要求。",
   "mice-bG9yZW56byBkZScgbWVkaWNp": "每门课程都以优质产品为核心，学习其生产过程及营养价值。烹饪文化与我们厨师的高超专业水准，确保学员在灶台前获得完整的学习体验。\n\n参与者可以跟随一道食谱的每一个准备步骤，从餐盘上的食物设计到最终品尝，品尝环节在厨师餐桌进行，氛围轻松，与其他课程参与者一同交流并点评最终成果。",
   "mice-d2VsbGEgZWR1Y2F0aW9u": "• 产品系列概览。\n\n• 每个产品家族的技术、优势及用途。\n\n• 如何执行店内护理操作。",
