   "mice-YWdyaWZpcm0": "关于暂停接受来自日本的考察团 ***\n\n<TYO-1288 2016年10月 荷兰、意大利、法国 农业电视考察团（日本农业新闻）>\n\n今后，我们将不再接受任何来自日本的团体。据说这与日本方面没有关联，且接受考察团并无益处。（截至2016年3月14日）\n\n-----------------------------------------\n\n▼YYJO050656-30SEP15 NOKH04 A) 经济联 荷兰/德国/法国 10天 30+1人\n\n日期：2015年10月1日（星期四）上午11:00-12:30（约一个半小时）\n人数：30+1人\n目的：了解荷兰园艺合作社\n考察内容：座谈、问答等\n演示\n- Agrifirm的角色和活动是什么？\n- 关于荷兰的农业和园艺产业。\n问答\n\n*语言：荷兰语\n　负责人：霍格兰德先生（Mr. Hoogland）的预约。\n\n*需提前提交名单 => 已发送。\n费用（含税）：\n每组273欧元（含增值税）。\n\n※付款及取消条件：\n需至少提前1个月全额预付。\n\n=> 我们正在安排预付款。\n\n※取消费用：\n自考察日期起计算，\n・提前4周以上：50欧元 + 21%增值税。\n・提前4-2周：100欧元 + 21%增值税。\n・2周以内：全额费用。\n\n※Kuoni NET：272.25欧元（含增值税）\n\n-----------------------------------------\n\n▼YYJO047759-01OCT14 NOKH04 A) 中央经济联 31+1人\n\n※AgriExperience安排\n日期：2014年10月3日（星期五）上午10:30-12:00（约一个半小时）\n负责人：希尔·霍格兰德先生（采购经理）\n\n考察内容：访谈等\n客户自我介绍\n讲座（负责人：霍格兰德先生）。\n　-Agrifirm的角色和活动。\n　-荷兰及欧盟国家农业产业的现状\n\n其他>\n* 活动当天，霍格兰德先生的助理温迪·哈默女士（Mrs. Wendy Hamer）将在Agrifirm迎接各位。（也会准备茶水）。\n\n※ 在节目开始时，霍格兰德先生希望代表团成员进行自我介绍。\n\n费用（含税）：\n每组302.50欧元\n\n※取消费用：\n自考察日期起计算，\n・提前4周以上：免费。\n・提前4-2周：50欧元 + 21%增值税。\n・提前2-1周：100欧元 + 21%增值税。\n・1周以内：全额费用。\n\n・付款方式：至少提前1个月全额预付（我们已支付）。\n付款后不可退款。\n\n----------------------------------------\n\n▼YYJO045195-02OCT13 NOKH04 A)中央经济联 荷兰/瑞士/法国 10天（GRQ NGO-0098）31+1人\n\n日期：2013年10月3日（星期四）上午09:30-11:00（约一个半小时）\n考察内容：访谈等\nAgrifarm介绍。\n讲座（负责人：霍格兰德先生）。\n-Agrifirm的角色和活动。\n-荷兰及欧盟国家农业产业的现状\n\n费用（含税）：全部含税（21%）\n\n◆考察（3个地点）：\n每组929.50欧元。\n・2个考察地点（Agrifarm + 菊花农场）\n每组544.50欧元\n・1个考察点（CBL）\n每组385欧元\n\n◆午餐（Wind in de Wilgen）\n每人18欧元（含6%税）。\n领队免费，无免费翻译。\n\n※取消费用：\n自考察日期起计算，\n・提前4周以上：免费。\n・提前4-2周：50欧元 + 21%增值税。\n・提前2-1周：100欧元 + 21%增值税。\n・1周以内：全额费用。\n\n<<原始提案>>\n2013年：GRQ NGO-0098 阿姆斯特丹、因特和巴黎农业产业考察（JA中央会 + 经济联）25-30+1人，2013年10月。截至2013年2月18日调查中。\n负责人：Agriexperience的玛丽安（供应商）\n\n※备注※\nHorticoop决定今年不接受任何此类代表团，因为其更注重商业利益和业务推广。我解释了过去访问的情况并进行协商，但他们表示无法接受。因此，作为替代方案，提议了同为园艺协会的“Agrifirm”。\n\n人数：25-30人\n考察日期：2013年10月3日（星期四）\n\n<拟定的全天考察行程>\n09:00 从Flora Holland Aalsmeer出发\n10:30-12:00 参观企业“Agrifirm”\n　接待人：希尔·霍格兰德先生\n　地址：Landgoedlaan 20, 7325 AW Apeldoorn\n  电话：(088) 488 12 00\n  网址：www.agrifirm.com\n  节目安排：来访者介绍，\n  霍格兰德先生关于Agrifirm角色和活动的讲座，\n  介绍荷兰及欧盟国家当前的农业产业状况\n\n负责人：希尔·霍格兰德先生\n节目安排（约一个半小时）：来访者自我介绍、讲座（负责人：霍格兰德先生）。\n讲座内容示例\n-Agrifirm的角色和活动。\n-荷兰及欧盟国家农业产业的现状\n\n12:00-13:00 在Agrifirm办公室用午餐（此为额外费用，稍后通知）\n14:00-15:00 参观Agrifirm乌得勒支仓库\n15:45-16:30 参观Horticoop Pijnacker门店（无导游，无Agri Experience安排，自由参观）\n  地址：Korteweg 2, 2641 GZ, Pijnacker\n  电话：015 361 51 71\n17:00-18:00 参观“Chrysanthenkwekerij Harry Wubben”菊花农场\n  地址：Langelandseweg 57, 2631 PS, Nootdorp(ZH)\n  电话：015-310 7418\n\n<费用和条件>\n\n费用（净价）：每组550欧元 + 21%增值税（115.50欧元）\n* 三个地点的考察安排费：Agrifirm Apeldoorn、Agrifirm Utrecht（仓库设施）和Harry Wubben（菊花农场）。\n\n・条件：\n1) 费用和条件适用于人数不确定的情况及19人。\n2) 取消费用。\n- 考察日期前4周以上...免费。\n- 考察日期前4周至2周内...50欧元+21%增值税\n- 考察日期前2周至1周内...100欧元+21%增值税\n- 考察日期前1周内...全额费用。\n\n如果我们同意此提案，玛丽安将在8月底向我们发送发票，届时她希望我们支付含增值税在内的550欧元全额费用。\n\n请注意，玛丽安提供了这个可能的行程，但她认为虽然技术上可行，但行程非常紧凑，如果路上有任何交通延误就没有缓冲时间，因此她建议团队不要去Horticoop门店，以便为其他更有用的考察腾出更多时间。\n\n------------------------------------------------------------\n\nYYJO031675-30SEP09 NOKH04 A) NOK 中央会经济联 电视考察团（GRQ NGO-0024）\n\n负责人：Agriexperience的玛丽安（供应商）\n\n■座谈示例（约一个半小时）\n- 关于Horticoop的角色和活动\n- 荷兰及欧洲农业产业的现状\n\n■考察费用\n每组350欧元（含增值税）\n\n* 以下参考案例安排了完全相同的内容。费用略有差异，但如果使用每组350欧元的标准，就没有问题。\nYYJO034963-06OCT10 NOKH04 A) NOK 中央会经济联 10天（GRQ NGO-0048）\n人数：29+1人\n时间：10月初\n\n◇费用\n每组525欧元（含增值税）\n* 与菊花农场考察一起安排，用于两个地点的考察安排费用。\n* 费用按最多30人计算。超过31人（最多45人）将额外收取119欧元，用于2个考察点的参观。（每组总计644欧元）",
