   "mice-Y2FoIGRyb250ZW4gLSBjaHJp": "★TTAO2092-02SEP07 HTPA02 A)别海高中 10+1+1人\n\n电话：00 31 (0) 320 29 34 78\n联系人：努尔·内斯肯斯女士（Mrs. Noor Neskens）\n\n13:30 - 15:30 农业学校 - Christelijke Agrarische Hogeschool (C.A.H.)\n内容：学校乳业教育说明、校园导览等\n\n「Waiboerhoeve实验农场」、「农业学校Christelijke Agrarische Hogeschool (C.A.H.)」、「Van Beek夫妇（围海造田地上的奶牛场）」共3个地点，由Agriexperience安排，每组1035欧元（含增值税）（需预付）。\n\n※电视考察团费用明细。\n1) 实验农场“Waiboerhoeve” + 午餐 = 535欧元（含增值税）\n2) Christelijke Agrarische Hogeschool (C.A.H.) = 300欧元（含增值税）\n3) Van Beek夫妇农场 = 200欧元（含增值税）\n\n------------------------------------------------\n\n★TTJO985562-20AUG06 TKKA06 A) 别海高中（JTGRQ-18E）12+1名老师\n\n日期时间：\n2006年8月22日 900-1100\n\n联系人：\n斯普伦格先生（Mr Sprenger）\n\n节目安排：\n--> 国际经理介绍乳业教育\n--> 校园及设施导览\n--> 参观学校奶牛场\n考察语言为荷兰语。\n\n考察费用：\n300欧元（含增值税）\n预付",
   "mice-b2xpaiByb3plbiAocm9zZSBm": "<FUK-0197 丹麦/荷兰农业与园艺电视考察团（鹿儿岛县立农业大学 - 农业）>\n\n截至2017年5月下旬，玫瑰种植农场的考察仍无法安排，情况没有变化。\n荷兰所有玫瑰种植者都被禁止接待访客，这是出于植物卫生方面的原因。去年发现了一种细菌，所有玫瑰种植者不得不关闭大门以保护他们的植物。\n\n---------------------------------------\n\n<YYJO056023-22OCT17 NOKH04 “AI) 爱知农业法人7”（NGO-0166）> 调查\n\n作为对2016年青枯病爆发的防御措施，荷兰大多数玫瑰种植者目前不允许外人进入他们的温室。\n\n因此，无法安排种植现场参观，尤其是在中大型设施中。\n\n---------------------------------------\n\n<TTAO003815-07OCT07 NTAD09 园艺博览会> 安排\n\n2007年10月\n联系人：P. VEYS先生\n\n09:30 - 10:30\n- 农场经理致欢迎辞\n- 园区参观\n- 问答环节\n\n考察费用（含税）：每组1050欧元（含增值税）（通过AgriExperience共7个电视考察团）\n\n---------------------------------------\n\n<TTJO962313-03OCT05 TKKE11 A) 栃木青年农业者（JTGRQ-36C）> 安排\n\n考察日期：2005年10月5日，上午1000-1115\n联系人：鲁德·奥利先生（Mr. Ruud Olij）\n\n考察费用（含税）：每组150欧元（通过AgriExperience安排）",
