   "mice-bmFrIChkdXRjaCBnZW5lcmFs": "<YYJO029326-01OCT08 NOKH04 A) 农协中央会经济连TV（GRQ NGO-0009）>\n\n2008年10月2日（周三）09:15-11:30 29+1人\n联系人：A. Van Pijlen女士\n内容：荷兰农业可追溯技术引进讲座 + 实验室参观\n入场费：每组600欧元（含税）\n\n★ 由于所有参观地点均通过供应商（AgriExperience）安排荷兰农业考察行程，需提前全额付款。\n＜费用示例＞\n每次参观的考察费根据内容（难度）不同而有所差异，但每组地点起价约为270欧元（含税）。总额可能略有不同，请仅作参考。\n*2008年基本费率（每个电视台地点）：225.00欧元 + 增值税（19%） = 267.75欧元",
   "mice-bXVuaWNpcGFsIGRyb250ZW4": "＜TTAO036318-28SEP09 NTAE14 A) 栃木青年农业者＞　16+1\n\n电视台日期与时间：2009年10月1日（周四）09:30-11:00\n内容与上一年度相同。\n\n-------------------------------------------------\n\n＜TTAO018880-29SEP08 NTAE14 A) 栃木青年农业者＞\n★ 考察项目示例\n联系人：J. Toes先生\nJ. Toes先生是城市规划与经济发展部郊区区域经理，负责推动农业、旅游、休闲和自然相关项目。\n\n09:30-11:00 座谈交流\n\n★ 考察费\n通过AgriExperience安排，四个地点（德龙滕市、奶牛场、草莓农场和番茄农场）共计900.00欧元（含增值税）。",
   "mice-YXJkIHZhbiB3ZWVz": "TTAO018880-29SEP08 NTAE14 A) 来自栃木青年农业者\n\n★ 考察项目示例\n11:30-12:30 参观农户\n\n★ 考察费（含税）\n2010年：通过AgriExperience安排，斯泰德布鲁克市四个地点（奶牛场、草莓农场和番茄农场）共计900.00欧元（含增值税）。\n2008年、2009年：通过AgriExperience安排，德龙滕市四个地点（奶牛场、草莓农场和番茄农场）共计900.00欧元（含增值税）。",
   "mice-YW1zdGVyZGFtIGNlbnRyZSBm": "<OOQF002234-05JUL09 NTAP04 A) 高松市议会>\n\n*活动安排\n\n时长 2小时\n- 欢迎致辞\n- 阿姆斯特丹建筑中心介绍\n- 未来项目展览\n- 问答环节\n\n*费用\n\n每组 357欧元（300欧元 + 19%增值税）\n发票结算\n\n*口译报告（内部信息）\n\n口译员在报告中评论道：“阿姆斯特丹方面还介绍了成功改造旧建筑以面向未来并进一步推进项目的成熟方法，客户对此非常满意。”\n\n---------------------------------------------\n\n<GRQ TYO-0085 阿姆斯特丹建筑与室内设计，巴黎化妆（东京设计师学院）>\n\n开放时间：周二至周六 13:00-17:00\n\n*ARCAM信息点可供您浏览书籍、文件、地图剪报，并向工作人员咨询有关阿姆斯特丹及周边地区最新建筑的问题。\n\n*展览空间定期举办讲座和活动。\n\n*该中心通常不专门为客户提供讲座，但经过协商，我们收到了对方愿意提供简单讲座的回复。\n内容：简要介绍ARCAM的职能及阿姆斯特丹建筑概况\n        （不含中心导览）\n时长：约1小时\n费用：每组150欧元 + 增值税（19%）",
   "mice-YXJjaGV4": "<TTAO185107-15NOV15 KHTE07 “A) 日本综合住生活”>\n\n☆日期和时间\n\n2015年11月19日（星期四）\n\n☆人数\n\n5人 + 口译\n\n☆地点\n\n午餐餐厅“De Kroonprince”\n\n☆活动安排\n\n阿姆斯特丹艾堡建筑之旅\n- 13:30在餐厅集合，乘车前往艾堡（乘坐Kuonii巴士）\n- 抵达后，进行区域参观及讲解\n\n<主题>\n填海造地的城市与住宅开发、城市结构、浮动住宅、工作/居住场所、可持续性等\n<部分亮点示例>\n- DKV和Kempe Thill设计的Blok 14\n- Lucas Ellermann van Vugt、KZG和Arons en Gelauff设计的购物中心及住宅\n- KSK、De Architecten Cie.、VMX architects和de Architectengroep、Claus+Kaan、Maccreanor Lavington Architects设计的住宅\n- Marlies Rohmer等设计的浮动住宅\n\n参观语言为荷兰语。\n\n时长：4小时\n\n活动安排：参观再开发区域，由建筑师担任向导，不仅讲解建筑本身，还介绍其背景（如阿姆斯特丹的发展历史、城市规划、基础设施、交通和停车问题等）。\n您将乘坐巴士参观西洛丹、艾堡和东部港区再开发区域，并经运河前往Q-park（仅停车场）。\n\n费用：750欧元（每4-5人）\n\n-------------------------------------\n\n<GRQ TYO-0085> 考察\n\n东部港区之旅\nhttp://www.archex.info/english/netherlands/amsterdam_eastern_docklands_borneo_sporenburg_java_knsm.html\n阿姆斯特丹东部湾区：KNSM岛、爪哇岛和波罗尼奥-斯波伦堡，约2小时30分钟带您参观最新的建筑综合体、住宅、商业及商务区开发项目。\n费用：每组360欧元（含增值税）",
   "mice-aW5nIGhvdXNl": "参观参考信息。\n（截至2008年，我们尚无安排考察的经验。）",
   "mice-dGhlIGVxdWFsaXR5IGFuZCBh": "培训项目“性别平等”\n会议围绕以下主题举行：（所需时间：2小时）\n\n- 挪威性别现状\n- 女性在政治中的参与和领导力\n- 性别平等与反歧视活动\n- 问答环节\n*之后为午餐会（从11:30开始）\n\n考察费用免费。\n\n----------------------------------------\n\n所需时间：约1小时\n\n负责人讲座\n・研究所介绍\n・促进性别平等的活动\n\n考察费用免费。\n\n----------------------------------------\n\n您将收到关于活动内容的讲座。\n2小时讲座，2000挪威克朗（团体价/29人）\n前身机构性别平等中心网站 - http://www.likestilling.no/english/",
