   "mice-dGVjaG5pY2FsIHZpc2l0IHRv": "参观活动将以港务局设施内的介绍会拉开序幕，由港务局代表进行讲解。在此环节中，代表将使用地图概述参观区域，并详细介绍港口的重要性、发展历程及港内各功能区域。介绍会结束后，参观将继续乘船进行。港务局代表将沿途解说，从水上视角展示港口的各项活动，包括易燃货物码头、物流平台等。",
   "mice-dGhlIGRlaGVzYSBvZiBzYWxh": "11:00 – 参观设施\n11:20 – 乘坐四驱车导览，穿越各个围场（包括母牛、牛犊、种公牛、一岁牛、公牛、花牛等）\n13:30 – 品尝在“Puerto de la Calderilla”和“San Miguel de Asperones”庄园蒙塔内拉期间饲养的伊比利亚橡果猪肉制品。包含Martín Berdugo或Dehesa de Ituero（El Pilar特别版）红葡萄酒或优质啤酒（每人2杯）、水和面包。",
   "mice-bmV3Y2FzdGxlIGNpdHkgY291": "行程安排为半天在纽卡斯尔听取BSF项目介绍，半天进行实地参观考察。\n\n考察费用免费，但我们要求客户携带纪念品，以表达对接待方的感谢之情。\n\n午餐为自助餐形式。我们仅被告知每人最高消费为15英镑，因此要求客户以当地现金支付。",
   "mice-Y29tbXVuaXR5IGhlYWx0aCBw": "在安排TTAO007389号行程时，我们参观了实际施工地点（诊所等），而非上述办公室所在的地址。\n听取会持续约一个半小时，内容涉及医疗创新、LIFT和NHS。\n\n考察费用免费，因此要求客户携带纪念品。",
   "mice-bmhzIGdyZWF0ZXIgZ2xhc2dv": "从13:30至16:00（两个半小时），举行了以下活动。\n・格拉斯哥ICT系统在医疗信息方面的应用\n・医院、诊所和全科医生之间ICT系统的使用\n・ICT在医学实验室、制药和医疗本身中的应用\n・ICT的未来发展\n\n考察费用免费。",
   "mice-ZW5nbGlzaCBwYXJ0bmVyc2hp": "<TTQF001922-12OCT'08 TCID01 A) KASSEIKA - LON> 行程示例 *电视已取消*\n\n实地考察（约2小时）：\n关于伦敦社会住房更新及项目，特别是泰晤士河口填海区的再生情况。\n\n考察费用免费。\n\n⇒ 行程确认后，考察负责人因故无法接待（国会夏季休会结束后，各方面提出了严肃议题，我们被迫参加那边的会议，加上与另外两个非政府组织的合并已确定，围绕英国合作伙伴关系的组织自身问题增多），因此客户实际上未能到访。",
   "mice-Y2FzdGxlbWlsayB0aW1lYmFu": "＜TTQF001922-12OCT'08 TCID01 A) KASSEIKA - LON＞\n\n我们安排了一场约两小时的听证讨论会，主题为利用社区货币推动社区振兴。\n\n我们支付了100英镑的捐款以覆盖访问费用。",
   "mice-YnJlbnQgY291bmNpbCByZWdl": "<TTQF001922-12OCT'08 TCID01 A) KASSEIKA - LON>\n\n访问示例（约2小时）：\n听证及现场参观。（包括介绍该HATS的历史、斯通布里奇更新项目、当前状况及未来规划等。）\n\n考察费用免费。",
